function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim();
}

function calculateVariantPricing(
  parentPrice: number,
  parentMrp: number,
  label: string,
  attrs: Record<string, string>,
  existingPrice?: number,
  existingMrp?: number
) {
  let price = existingPrice || parentPrice;
  let mrp = existingMrp || parentMrp;

  const combinedText = (label + " " + Object.values(attrs).join(" ")).toLowerCase();
  let diff = 0;

  // High demand color adjustment: Black / White / Navy / Stealth
  const isHighDemandColor =
    combinedText.includes("black") ||
    combinedText.includes("white") ||
    combinedText.includes("stealth") ||
    combinedText.includes("midnight");

  if (isHighDemandColor && !combinedText.includes("white border") && !combinedText.includes("pack_of_2")) {
    if (price < 100) diff += 4;
    else if (price < 250) diff += 10;
    else diff += 15;
  }

  // Size increment adjustment
  if (combinedText.includes("xxl") || combinedText.includes("3xl") || combinedText.includes("38") || combinedText.includes("44")) {
    diff += 15;
  } else if (combinedText.includes("xl") || combinedText.includes("36") || combinedText.includes("42")) {
    diff += 10;
  } else if (combinedText.includes("large") && !combinedText.includes("small")) {
    diff += 15;
  }

  price += diff;
  mrp += diff * 3;

  return { price, mrp };
}

function generateUnrolledCatalog(baseProducts: MasterProduct[]): MasterProduct[] {
  // 1. Group variants by parent product
  const productVariantGroups: MasterProduct[][] = [];

  for (const p of baseProducts) {
    if (!p.variantItems || p.variantItems.length === 0) {
      if (p.image && p.image.trim() !== "" && !p.image.endsWith(".jpg")) {
        productVariantGroups.push([p]);
      }
      continue;
    }

    const unrolledForP: MasterProduct[] = [];
    p.variantItems.forEach((v, idx) => {
      // Gallery & Image: prioritize variant image, then parent image
      const gallery = v.gallery && v.gallery.length > 0 ? v.gallery : (p.gallery || []);
      const image = v.image || p.image || gallery[0]?.url;

      // Filter out any variant that does not have a valid real photo
      if (!image || image.trim() === "" || image.endsWith(".jpg")) {
        return;
      }

      const { price, mrp } = calculateVariantPricing(
        p.price,
        p.mrp,
        v.label,
        v.attributes,
        v.price,
        v.mrp
      );

      const baseName = p.name.includes(" – ") ? p.name.split(" – ")[0] : p.name;
      const unrolledName = `${baseName} – ${v.label}`;
      const unrolledSlug = slugify(`${baseName}-${v.label}`);
      const unrolledId = `${p.id}-${v.id}`;
      const unrolledSku = v.sku || `${p.sku}-${v.id.toUpperCase()}`;

      // Backward compatibility aliases: first variant retains parent slug & aliases so old links never 404
      const aliases: string[] = [];
      if (idx === 0) {
        aliases.push(p.slug);
        aliases.push(p.id);
        if (p.aliases) {
          aliases.push(...p.aliases);
        }
      }
      if (v.id) aliases.push(v.id);
      aliases.push(`${p.id}-${v.id}`);

      const newProd: MasterProduct = {
        ...p,
        id: unrolledId,
        slug: unrolledSlug,
        aliases: Array.from(new Set(aliases)),
        sku: unrolledSku,
        name: unrolledName,
        price,
        mrp,
        moq: v.moq || p.moq,
        image,
        gallery,
        variantItems: p.variantItems,
        variantOptions: p.variantOptions,
        tags: Array.from(
          new Set([
            ...p.tags,
            ...v.label.toLowerCase().split(/\s+/),
            ...Object.values(v.attributes).map((a) => a.toLowerCase()),
          ])
        ),
      };

      unrolledForP.push(newProd);
    });

    if (unrolledForP.length > 0) {
      productVariantGroups.push(unrolledForP);
    }
  }

  // 2. JUGGLE / INTERLEAVE VARIANTS SO SAME PRODUCT VARIANTS DO NOT APPEAR IN SEQUENCE
  const byCategory = new Map<string, MasterProduct[][]>();
  for (const group of productVariantGroups) {
    const cat = group[0].categorySlug || "other";
    if (!byCategory.has(cat)) byCategory.set(cat, []);
    byCategory.get(cat)!.push(group);
  }

  const result: MasterProduct[] = [];
  for (const [_, groups] of byCategory.entries()) {
    let maxLen = 0;
    for (const g of groups) {
      if (g.length > maxLen) maxLen = g.length;
    }

    // Interleave round-robin: pick variant i across all products
    for (let i = 0; i < maxLen; i++) {
      for (const g of groups) {
        if (i < g.length) {
          result.push(g[i]);
        }
      }
    }
  }

  return result;
}

export const MASTER_PRODUCTS: MasterProduct[] = generateUnrolledCatalog(RAW_MASTER_PRODUCTS);

// Helper: get unique categories
export function getCategories(): string[] {
  return [...new Set(MASTER_PRODUCTS.map((p) => p.category))];
}

// Helper: get subcategories for a category
export function getSubCategories(category: string): string[] {
  return [
    ...new Set(
      MASTER_PRODUCTS.filter((p) => p.category === category).map(
        (p) => p.subCategory
      )
    ),
  ];
}

// Helper: get products by category slug
export function getProductsByCategorySlug(slug: string): MasterProduct[] {
  return MASTER_PRODUCTS.filter((p) => p.categorySlug === slug);
}

// Helper: get products by subcategory slug
export function getProductsBySubCategorySlug(slug: string): MasterProduct[] {
  return MASTER_PRODUCTS.filter((p) => p.subCategorySlug === slug);
}

// Helper: get product by slug
export function getProductBySlug(slug: string): MasterProduct | undefined {
  return MASTER_PRODUCTS.find((p) => p.slug === slug || p.id === slug || (p.aliases && p.aliases.includes(slug)));
}

// Helper: find product by id or slug
export function findProductByIdOrSlug(idOrSlug: string): MasterProduct | undefined {
  return MASTER_PRODUCTS.find(
    (p) =>
      p.slug === idOrSlug ||
      p.id === idOrSlug ||
      (p.aliases && p.aliases.includes(idOrSlug)) ||
      (p.variantItems && p.variantItems.some((v) => v.id === idOrSlug || v.sku === idOrSlug))
  );
}

// Helper: search products
export function searchProducts(query: string, categorySlug?: string): MasterProduct[] {
  const q = query.toLowerCase();
  return MASTER_PRODUCTS.filter((p) => {
    const matchesQuery =
      p.name.toLowerCase().includes(q) ||
      p.category.toLowerCase().includes(q) ||
      p.subCategory.toLowerCase().includes(q) ||
      p.tags.some((t) => t.toLowerCase().includes(q)) ||
      (p.variantItems && p.variantItems.some((v) => v.label.toLowerCase().includes(q) || Object.values(v.attributes).some(attr => attr.toLowerCase().includes(q)))) ||
      (p.variants && p.variants.some((v) => v.value.toLowerCase().includes(q)));
    const matchesCat = !categorySlug || categorySlug === "all" || p.categorySlug === categorySlug;
    return matchesQuery && matchesCat;
  });
}

// Helper: get related products
export function getRelatedProducts(productOrId: MasterProduct | string, limit = 5): MasterProduct[] {
  const prod = typeof productOrId === "string" ? findProductByIdOrSlug(productOrId) : productOrId;
  if (!prod) return MASTER_PRODUCTS.slice(0, limit);
  return MASTER_PRODUCTS.filter(
    (p) =>
      p.id !== prod.id &&
      (p.categorySlug === prod.categorySlug ||
        p.subCategorySlug === prod.subCategorySlug)
  ).slice(0, limit);
}

